  (* [comment removed for export] *)
  Lemma pcg_B : forall regs m (pixd pixs : Z),
    getr regs 10 = Z_to_bv 64 0 -> getr regs 8 = Z_to_bv 64 pixd -> getr regs 9 = Z_to_bv 64 pixs ->
    exists regs',
      msteps SEGS (mkst regs (0x6d4c8 : word) m rom) (mkst regs' (0x6cfd0 : word) m rom)
      /\ getr regs' 1 = Z_to_bv 64 0x6d57c /\ getr regs' 10 = Z_to_bv 64 pixd /\ getr regs' 11 = Z_to_bv 64 pixs
      /\ regs_agree (fun r => In r [1; 10; 11]%list) regs regs'.
Proof.
